// ── Expansion ────────────────────────────────────────────────────────────────

const round1 = (v) => Math.round(v * 10) / 10;

function finalizeSpec(raw) {
  const s = { ...FIELD_DEFAULTS, ...raw };
  // Derive metric fuel economy + combined figures from MPG when not authored
  if (s.mpgCity != null && s.L100kmCity == null) s.L100kmCity = round1(235.215 / s.mpgCity);
  if (s.mpgHwy != null && s.L100kmHwy == null) s.L100kmHwy = round1(235.215 / s.mpgHwy);
  if (s.mpgCombined == null && s.mpgCity != null && s.mpgHwy != null) {
    s.mpgCombined = Math.round(1 / (0.55 / s.mpgCity + 0.45 / s.mpgHwy));
  }
  if (s.L100kmCombined == null && s.mpgCombined != null) s.L100kmCombined = round1(235.215 / s.mpgCombined);
  if (s.mpgCity == null) { s.L100kmCity = s.L100kmCity ?? null; s.mpgCombined = s.mpgCombined ?? null; s.L100kmHwy = s.L100kmHwy ?? null; s.L100kmCombined = s.L100kmCombined ?? null; }
  return s;
}

function buildSpecsMap(specData) {
  const map = {};
  for (const { make, model, generations } of specData) {
    for (const gen of generations) {
      const [from, to] = gen.years;
      const genBase = finalizeSpec(gen.base);
      const trimSpecs = {};
      for (const [trim, overrides] of Object.entries(gen.trims || {})) {
        trimSpecs[trim] = Object.keys(overrides).length
          ? finalizeSpec({ ...gen.base, ...overrides })
          : genBase; // share the base object when the trim has no overrides
      }
      for (let y = from; y <= to; y++) {
        map[`${make}|${model}|${y}`] = genBase;
        for (const [trim, spec] of Object.entries(trimSpecs)) {
          map[`${make}|${model}|${y}|${trim}`] = spec;
        }
      }
    }
    // Make|Model fallback → newest generation base
    const newest = generations[generations.length - 1];
    map[`${make}|${model}`] = finalizeSpec(newest.base);
  }
  return map;
}

export const VEHICLE_SPECS = buildSpecsMap(SPEC_DATA);

// Case-insensitive index so lookups tolerate "RAM" vs "Ram", "HONDA" vs "Honda"
const SPECS_LOWER = {};
for (const key of Object.keys(VEHICLE_SPECS)) SPECS_LOWER[key.toLowerCase()] = VEHICLE_SPECS[key];

/**
 * Look up specs with progressive fallback:
 *   "Make|Model|Year|Trim" → "Make|Model|Year" → "Make|Model" → null
 */
export function getSpecsForVehicle(make, model, year, trim) {
  if (!make || !model) return null;
  const y = String(year ?? '').trim();
  const t = String(trim ?? '').trim();
  const tryKeys = [];
  if (y && t) tryKeys.push(`${make}|${model}|${y}|${t}`);
  if (y) tryKeys.push(`${make}|${model}|${y}`);
  tryKeys.push(`${make}|${model}`);
  for (const key of tryKeys) {
    const hit = VEHICLE_SPECS[key] ?? SPECS_LOWER[key.toLowerCase()];
    if (hit) return hit;
  }
  return null;
}
